// The generation span, attribute by attribute, against what the Python SDK writes for the same requests.
// test/golden/python-spans.json is generated by test/golden/generate.py from zoroval-python 0.2.0 (the
// real Python integration, against the same fake OpenAI server); scenarios.json drives both sides.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test, afterEach, before, after } from "node:test";
import OpenAI from "openai";
import * as zoroval from "../dist/node.js";
import { KEY, startGateway } from "./gateway.mjs";
import { startFakeOpenAI } from "./fake-openai.mjs";

const read = (name) => JSON.parse(readFileSync(new URL(`./golden/${name}`, import.meta.url), "utf8"));
const scenarios = read("scenarios.json");
const golden = Object.fromEntries(read("python-spans.json").map((g) => [g.name, g.span]));

let fake;
before(async () => { fake = await startFakeOpenAI(); });
after(async () => { await fake.close(); });
afterEach(async () => { await zoroval.shutdown(1000); });

// Differences that are the library's or the language's, not ours (see the header of integrations/openai.ts):
const VOLATILE = new Set(["server.port"]); // the fake's port differs per run
const NUMBER_ONLY = new Set(["gen_ai.response.time_to_first_chunk"]); // a duration: present, a number

async function trace(mode, scenario) {
  const gateway = await startGateway();
  zoroval.init({ apiKey: KEY, ingestUrl: gateway.url, flushIntervalMs: 20 });
  const fetchFn = mode === "fetch" ? zoroval.wrapFetch(globalThis.fetch, { baseURLs: [fake.url] }) : undefined;
  const client = new OpenAI({ apiKey: "sk-test", baseURL: fake.url, maxRetries: 0, ...(fetchFn ? { fetch: fetchFn } : {}) });
  const openai = mode === "wrap" ? zoroval.wrapOpenAI(client) : client;
  const api = scenario.api === "chat" ? openai.chat.completions : openai.responses;
  await zoroval.conversation("golden", () => zoroval.turn({ input: "q" }, async () => {
    try {
      const result = await api.create(structuredClone(scenario.body));
      if (scenario.body.stream) for await (const event of result) void event;
    } catch (error) {
      assert.ok(scenario.expectError, String(error));
    }
  }));
  await zoroval.flush(3000);
  const spans = gateway.spans().filter((s) => s.attrs["zoroval.observation.type"] === "generation");
  await gateway.close();
  assert.equal(spans.length, 1);
  return spans[0];
}

function compare(name, ts, py, skip = new Set()) {
  assert.equal(ts.name, py.name, `${name}: span name`);
  assert.equal(ts.kind, py.kind, `${name}: span kind`);
  assert.equal(ts.status?.code === 2 ? "ERROR" : "UNSET", py.status, `${name}: status`);
  assert.deepEqual((ts.events ?? []).map((e) => e.name), py.events.map((e) => e.name), `${name}: events`);
  const keys = new Set([...Object.keys(py.attributes), ...Object.keys(ts.attrs)]);
  for (const key of [...keys].sort()) {
    if (skip.has(key)) continue;
    const expected = py.attributes[key];
    const actual = ts.attrs[key];
    if (VOLATILE.has(key)) { assert.equal(typeof actual, typeof expected, `${name}: ${key}`); continue; }
    if (NUMBER_ONLY.has(key)) { assert.equal(typeof actual, "number", `${name}: ${key}`); assert.equal(typeof expected, "number", `${name}: ${key} (python)`); continue; }
    assert.deepEqual(actual, expected, `${name}: ${key}`);
  }
}

for (const mode of ["wrap", "fetch"]) {
  for (const scenario of scenarios) {
    test(`golden (${mode === "wrap" ? "wrapOpenAI" : "wrapFetch"}): ${scenario.name} matches the Python span`, async () => {
      const ts = await trace(mode, scenario);
      const py = golden[scenario.name];
      if (scenario.expectError) {
        // The error text and class come from each language's openai library, so only the shape is compared.
        assert.equal(py.status, "ERROR");
        assert.equal(ts.status.code, 2);
        if (mode === "wrap") {
          assert.deepEqual(ts.events.map((e) => e.name), ["exception"]);
          assert.match(ts.status.message, /^RateLimitError: /);
          assert.equal(ts.attrs["error.type"], py.attributes["error.type"]);
        } else {
          // Over plain fetch the app gets the HTTP response, not an exception: no exception event, the
          // provider's own message and error type.
          assert.equal(ts.events, undefined);
          assert.match(ts.status.message, /^429 Rate limit reached/);
          assert.equal(ts.attrs["error.type"], "requests");
        }
        for (const key of Object.keys(py.attributes)) {
          if (!VOLATILE.has(key) && key !== "error.type") assert.deepEqual(ts.attrs[key], py.attributes[key], `${scenario.name}: ${key}`);
        }
        return;
      }
      compare(scenario.name, ts, py);
    });
  }
}
